#pragma once
// Serve build-time gzip-compressed HTML directly from flash for modern browsers.
// Preserve the original flash-backed HTML for HTTP clients that do not offer
// gzip. In either path, no whole HTML page is copied to an Arduino String.
// This fixes large transient allocations in ESPAsyncWebServer's response
// staging: on 3.6.0, AsyncAbstractResponse::_ack mallocs the bytes it sends.

#include <Arduino.h>
#include <ESPAsyncWebServer.h>
#include "ebtks_firmware_options.h"
#include "ebtks_static_pages_gzip.h"  // generated by PlatformIO pre-script

inline bool ebtksHtmlAcceptsGzip(AsyncWebServerRequest *request) {
  if (!request->hasHeader("Accept-Encoding")) return false;
  const String value = request->getHeader("Accept-Encoding")->value();
  // Modern browser and curl --compressed use gzip. Never send a gzip
  // entity to a client that only asked for the identity representation.
  return value.indexOf("gzip") >= 0 &&
         value.indexOf("gzip;q=0") < 0;
}

inline void ebtksServeStaticHtml(AsyncWebServerRequest *request,
                                 const uint8_t *plainData,size_t plainLength,
                                 const uint8_t *gzipData,size_t gzipLength,
                                 const char *allocationFailure) {
  const bool gzip=ebtksHtmlAcceptsGzip(request);
  AsyncWebServerResponse *response=request->beginResponse(
      200,"text/html; charset=utf-8",
      gzip?gzipData:plainData,gzip?gzipLength:plainLength);
  if (!response) {
    request->send(503,"text/plain",allocationFailure);
    return;
  }
  if (gzip) response->addHeader("Content-Encoding","gzip");
  response->addHeader("Vary","Accept-Encoding");
  response->addHeader("Cache-Control","no-store");
  request->send(response);
}
